			If, under conditions 
			\eqref{umova_raz}-\eqref{umova_try}, the function $m(x)$ attains its minimum at the unique point  $0\in\Omega$ and \eqref{nond} is satisfied, then the first $n$  eigenvalues of $\mathcal{L}_\varepsilon$ (for any $n$ fixed) are given by the asymptotic formula
	\begin{equation*}
		\lambda_\varepsilon^{(k)}=m(0)+\varepsilon\mu^{(k)}+\bar o(\varepsilon),
	\end{equation*}
	where $\mu^{(k)}$ are the eigenvalues of harmonic oscillator, 	
	\begin{equation}
			\mathcal{L}_0 \rho=-\frac{\vartheta}{2d} \Delta \rho (\xi)+
			\frac{1}{2}\partial^2_{x_ix_j} m(0)\xi_i\xi_j \, \rho (\xi) \quad {\rm in} \ \mathbb{R}^d.
				\label{harm_osc}
		\end{equation} 
	Moreover, the corresponding rescaled and properly normalized eigenfunctions
	$ \rho_\varepsilon (\xi/\sqrt{\varepsilon})$    of $\mathcal{L}_\varepsilon$ $L^2$-strongly converge, up to a subsequence, to the eigenfunctions of $\mathcal{L}_0$.
			\label{Th21}

\label{Th22}              
		Assume that 	\eqref{umova_raz}--\eqref{umova_try} hold, moreover, $J$ is a $C^2$-function with compact support. Assume also that the function $m(x)$ attains its minimum at the unique point  $0\in\partial\Omega$ and \eqref{2.9},  \eqref{2.10} are satisfied, then the first $n$  eigenvalues of $\mathcal{L}_\varepsilon$ (for any $n$ fixed) are given by the asymptotic formula
\begin{equation*}
		\lambda_\varepsilon^{(k)}=m(0)+\varepsilon^{2/3}\Lambda_0+\varepsilon(\mu^{(k)} +\alpha q_0) +\bar o(\varepsilon),
\end{equation*}
where $\Lambda_0$ is the principal eigenvalue 
		of the equation 
		\begin{equation}
			-\frac{\vartheta}{2d} \, \phi_0''(q) + \alpha q \phi_0(q)=\Lambda_0 \phi_0(q), \quad q>0, 
			\label{Airy_sln}
		\end{equation}
with the boundary condition $\phi_0(0)=0$;
$\mu^{(k)}$ are the eigenvalues of the $(d-1)$-dimensional harmonic oscillator 
\begin{equation}
			\mathcal{L}_0 \psi=-\frac{\vartheta}{2d} \Delta \psi (\xi)+\frac{1}{2}\left(\alpha \kappa_i\xi_i^2 +
			\partial^2_{x_ix_j} m(0)\xi_i\xi_j\right)\psi (\xi) \quad {\rm in} \ \mathbb{R}^{d-1};
			\label{harm_osc_bound}
\end{equation} 
	 $q_0$ is defined in 	Corollary \ref{cor72}.
		\label{Th22}

