(where $I_0$ is given by \eqref{I_0}). Moreover, it converges as $\xi\to\infty$ (faster than any negative power of $\xi$) to some constant $q_0>0$, 
\begin{equation*}

q_0=\lim_{\xi\to\infty}\tilde \varphi(\xi),
\end{equation*} 	
and the function $\xi+\tilde\varphi(\xi)$ is bounded away form zero on $[0,+\infty)$,
\begin{equation*}

\min_{\xi\in[0;\infty)}(\xi +\tilde \varphi(\xi))> 0.
\end{equation*}

For every $\xi\geq 0$ we have
\begin{equation*}
	\begin{aligned}
		-\int\limits_{0}^{\infty}
	I_0\big(\tilde\xi-\xi\big) \big(\tilde\xi+\tilde \varphi(\tilde\xi)\big) d\tilde\xi+
\xi+\tilde\varphi(\xi)
		=-\int\limits_{-\infty}^{\infty} I_0\big(\tilde\xi-\xi\big)
		\tilde\xi d\tilde\xi+\xi=0.

	\end{aligned}
\end{equation*}
Therefore $U(\xi)=\xi+\tilde \varphi(\xi)$ satisfies
	\begin{equation}
	-\int\limits_{0}^{\infty}
	I_0\big(\xi-\tilde\xi\big)U(\tilde\xi)d\tilde\xi+
	U(\xi)=0, \ \ \xi\geq 0.
	\label{cor_p3}
\end{equation}

Let $\xi_m$ be a minimum point of $U(\xi)$ on $[0,\infty)$. We claim  that  $U(\xi_m)>0$.






Assume by contradiction that $U(\xi_m)\leq 0$.

From \eqref{cor_p3} we have 





\begin{equation*}
	\int\limits_{-\infty}^{\infty}
	I_0\big(\xi_m-\tilde\xi\big)U(\xi_m)d\tilde\xi=U(\xi_m)=\int\limits_{0}^{\infty}
	I_0\big(\xi_m-\tilde\xi\big)U(\tilde\xi)d\tilde\xi 
\end{equation*}
and, consequently,
\begin{equation}
	\int\limits_{-\infty}^{0}
	I_0\big(\xi_m-\tilde\xi\big)U(\xi_m)d\tilde\xi=\int\limits_{0}^{\infty}
	I_0\big(\xi_m-\tilde\xi\big)\Big(U(\tilde\xi)-U(\xi_m)\Big)d\tilde\xi. 	\label{cor_p4}
\end{equation}
Since  $I_0(z)\geq 0$,  the left-hand side of \eqref{cor_p4} is nonpositive while the right-hand side                    
is nonnegative. Moreover, as $I_0(0)>0$, $U(\xi)=U(\xi_m)$ for all $\xi$ in a neighborhood of $\xi_m$ (within $[0,\infty)$). Therefore the set of minimum points of the function $U(\xi)$ is open (in the induced topology of $[0,\infty)$), and at the same time it is closed by the continuity of $U(\xi)$. Since $[0,\infty)$ is connected and $U(\xi)\to \infty $ as $\xi\to\infty$, the set of minimum points of $U(\tilde\xi)$  must be empty, a contradiction. Thus $U(\xi)\geq U(\xi_m)>0$.

